#!/bin/bash
set -e
echo '[matterctl] install: writing project files'

cat > package.json << 'EOF'
{
  "name": "rdk-matter-device-control",
  "version": "2.0.0",
  "description": "Matter device control via local broker + bridge",
  "main": "index.js",
  "license": "ISC"
}
EOF

cat > index.js << 'EOF'
const axios = require('axios');
const mqtt = require('mqtt');

const BROKER        = process.env.MATTERCTL_BROKER_URI   || 'tcp://192.168.10.1:1883';
const HUB_API       = process.env.MATTERCTL_HUB_API      || 'http://192.168.1.201:8089/cgi-bin/matterapi.ha';
const CONTROL_TOPIC = process.env.MATTERCTL_CONTROL_TOPIC || 'rdk/matter/device/control';
const RESULT_TOPIC  = process.env.MATTERCTL_RESULT_TOPIC  || 'rdk/matter/device/control/result';

console.log('[matterctl] connecting to local broker ' + BROKER);
const client = mqtt.connect(BROKER, {
  clientId: 'matterctl-' + Math.random().toString(36).slice(2, 10),
  reconnectPeriod: 3000,
  keepalive: 30,
});

function publishResult(body) {
  const payload = JSON.stringify(body);
  client.publish(RESULT_TOPIC, payload, { qos: 1 });
  console.log('[matterctl] result:', payload);
}

client.on('connect', function () {
  console.log('[matterctl] connected; control=' + CONTROL_TOPIC + ' result=' + RESULT_TOPIC);
  client.subscribe(CONTROL_TOPIC, { qos: 1 }, function (err) {
    if (err) console.error('[matterctl] subscribe failed:', err.message);
    else console.log('[matterctl] subscribed; waiting for commands');
  });
});
client.on('error', function (e) { console.error('[matterctl] mqtt error:', e && e.message); });
client.on('reconnect', function () { console.log('[matterctl] reconnecting...'); });
client.on('close', function () { console.log('[matterctl] connection closed'); });

client.on('message', function (topic, payload) {
  var raw = payload.toString('utf-8');
  console.log('[matterctl] command received on ' + topic + ': ' + raw);
  var msg;
  try { msg = JSON.parse(raw); }
  catch (e) { publishResult({ requestId: null, success: false, error: 'invalid JSON payload' }); return; }
  var requestId = msg.requestId || null;
  delete msg.requestId;
  if (!msg.cmd) msg.cmd = 'CONTROL_DEVICE';
  var url = HUB_API + '?' + msg.cmd;
  console.log('[matterctl] hub call: ' + JSON.stringify(msg) + ' -> ' + url);
  axios.post(url, msg, { timeout: 15000, headers: { 'Content-Type': 'application/json' } })
    .then(function (res) {
      console.log('[matterctl] hub status ' + res.status + ': ' + JSON.stringify(res.data));
      publishResult({ requestId: requestId, success: true, hubResponse: res.data });
    })
    .catch(function (e) {
      var hubData = e && e.response ? e.response.data : null;
      var detail = hubData ? JSON.stringify(hubData) : (e && e.message);
      console.error('[matterctl] hub call failed:', detail);
      publishResult({ requestId: requestId, success: false, error: detail, hubResponse: hubData });
    });
});

// Keep the event loop alive for the lifetime of the component.
setInterval(function () {}, 1 << 30);
EOF

echo '[matterctl] install: npm install (Node-10-safe pins)'
npm install mqtt@4.3.7 axios@0.27.2 --cache /tmp/npm-cache --omit=dev
echo '[matterctl] install: done'
